1: import type { Quat, Vec3 } from '../contracts/math';
2: import type { ObstacleDescriptor } from '../courses/types';
3: import { basePoseOf, clonePose, isMovingObstacle } from './descriptor';
4: import type { ObstaclePose } from './types';
5: 
6: const DEFAULT_AXIS: Vec3 = { x: 0, y: 1, z: 0 };
7: const EPSILON = 1e-8;
8: 
9: /** Degenerate axes fall back to +Y so authored data can never stall a spinner. */
10: export function normalizeAxis(axis: Vec3): Vec3 {
11:   const length = Math.hypot(axis.x, axis.y, axis.z);
12:   if (!Number.isFinite(length) || length < EPSILON) return { ...DEFAULT_AXIS };
13:   return { x: axis.x / length, y: axis.y / length, z: axis.z / length };
14: }
15: 
16: export function quatFromAxisAngle(axis: Vec3, angle: number): Quat {
17:   const unit = normalizeAxis(axis);
18:   const half = angle * 0.5;
19:   const sin = Math.sin(half);
20:   return { x: unit.x * sin, y: unit.y * sin, z: unit.z * sin, w: Math.cos(half) };
21: }
22: 
23: export function multiplyQuat(a: Quat, b: Quat): Quat {
24:   return {
25:     x: a.w * b.x + a.x * b.w + a.y * b.z - a.z * b.y,
26:     y: a.w * b.y - a.x * b.z + a.y * b.w + a.z * b.x,
27:     z: a.w * b.z + a.x * b.y - a.y * b.x + a.z * b.w,
28:     w: a.w * b.w - a.x * b.x - a.y * b.y - a.z * b.z,
29:   };
30: }
31: 
32: /**
33:  * Pose of an obstacle `elapsedSeconds` after its hole started. Pure and
34:  * deterministic: the same elapsed time always yields the same pose, so replays
35:  * and fixed-step physics stay in sync.
36:  */
37: export function evaluateObstaclePose(
38:   descriptor: ObstacleDescriptor,
39:   elapsedSeconds: number,
40:   base: ObstaclePose = basePoseOf(descriptor.transform),
41: ): ObstaclePose {
42:   if (!isMovingObstacle(descriptor)) return clonePose(base);
43: 
44:   const time = Number.isFinite(elapsedSeconds) ? elapsedSeconds : 0;
45:   const motion = descriptor.motion;
46:   const phase = motion.phase ?? 0;
47: 
48:   if (motion.kind === 'rotate') {
49:     const spin = quatFromAxisAngle(motion.axis, phase + motion.speed * time);
50:     return { position: { ...base.position }, rotation: multiplyQuat(base.rotation, spin) };
51:   }
52: 
53:   const unit = normalizeAxis(motion.axis);
54:   const offset = Math.sin(phase + motion.speed * time) * (motion.distance ?? 0);
55:   return {
56:     position: {
57:       x: base.position.x + unit.x * offset,
58:       y: base.position.y + unit.y * offset,
59:       z: base.position.z + unit.z * offset,
60:     },
61:     rotation: { ...base.rotation },
62:   };
63: }
